def is_valid_day(year: int, month: int, day: int) -> bool:
    """Buggy: off-by-one on the maximum day boundary.

    Symptom:
    - Uses `< max_day` instead of `<= max_day`, so the last day of a month is rejected.
    """
    if year < 1:
        return False
    if month < 1 or month > 12:
        return False
    if day < 1:
        return False

    def is_leap(y: int) -> bool:
        if y % 400 == 0:
            return True
        if y % 100 == 0:
            return False
        return y % 4 == 0

    leap = is_leap(year)

    if month == 2:
        max_day = 29 if leap else 28
    elif month in (4, 6, 9, 11):
        max_day = 30
    else:
        max_day = 31

    return day < max_day

